def election(rid,year,place,route,party,result,votes,opp,oppvotes,valid,polled,electors,ns,phase,note):
    finding=f'{result}: {votes:,} votes against {oppvotes:,} for {opp}.' if votes is not None and oppvotes is not None else f'{result}; {route.split(" / ")[0]} selection.'
    fields={'Year':year,'Constituency / jurisdiction':place,'Result':result,'Finding':finding,'House / route':route,'Party / alliance':party,'Candidate votes':votes,'Principal opponent':opp,'Opponent votes':oppvotes,'Valid votes':valid,'Total polled':polled,'Electorate':electors,'Vote share':votes/valid if votes is not None and valid else None,'Signed vote margin':votes-oppvotes if votes is not None and oppvotes is not None else None,'Margin unit':'Individual votes' if votes is not None else 'Not applicable / not retrieved','Turnout percent':round(polled/electors*100,2) if polled and electors else None,'Geography / selection caution':note}
    p={'Finding':ns,'House / route':ns}
    if votes is not None: p['Candidate votes']=ns; p['Opponent votes']=ns
    if valid: p['Valid votes']=ns; p['Vote share']=ns
    if polled: p['Total polled']=ns; p['Electorate']=ns
    return add('Elections',rid,fields,ns,proof=p,phase=phase,priority='High',note=note)
